"""Extract the Snowflake tables and views read by a Power Query (M) expression.

The M code is split into tokens (strings, names, brackets) and walked with
bracket nesting, so function arguments and records are read as structures,
not matched as text. Two ways of reading Snowflake are recognized:

* Navigation generated by the Snowflake connector::

      Source = Snowflake.Databases("acme.snowflakecomputing.com", "WH"),
      Db = Source{[Name="ANALYTICS", Kind="Database"]}[Data],
      Sch = Db{[Name="SALES", Kind="Schema"]}[Data],
      Orders = Sch{[Name="ORDERS", Kind="Table"]}[Data]

  The ``Implementation="2.0"`` connector can leave ``Kind`` out; the level is
  then taken from the position (database, then schema, then object).

* Native SQL, ``Value.NativeQuery(<database>, <sql>, ...)``, wherever the
  database argument comes from (a previous step, or the connector call
  written inline). The SQL is parsed with sqlglot (Snowflake dialect) and
  every table or view it reads is reported, qualified with the database and
  schema navigated to when the query doesn't name them.

Names and SQL given through Power Query parameters, text steps
(``Query = "select ..."``) or ``&`` concatenations are resolved. A name that
can't be resolved is reported as ``{Name}``; SQL that can't be resolved or
parsed is reported as one ``SQL not parsed`` row holding the code.
"""

import re
from dataclasses import dataclass, field

import sqlglot
from sqlglot import exp

SQL_REFERENCE = "SQL reference"
SQL_NOT_PARSED = "SQL not parsed"
UNKNOWN_OBJECT_KIND = "Table or view"
OBJECT_KINDS = {"Table", "View", UNKNOWN_OBJECT_KIND}

M_TOKEN_PATTERN = re.compile(
    r"""
      (?P<comment>//[^\n]*|/\*.*?\*/)
    | (?P<string>"(?:[^"]|"")*")
    | (?P<quoted>\#"(?:[^"]|"")*")
    | (?P<name>[A-Za-z_][\w.]*)
    | (?P<space>\s+)
    | (?P<symbol>.)
    """,
    re.VERBOSE | re.DOTALL,
)
CLOSING_BRACKETS = {"(": ")", "[": "]", "{": "}"}
M_STRING_ESCAPES = {"#(lf)": "\n", "#(cr)": "\r", "#(tab)": "\t", "#(#)": "#"}


@dataclass(frozen=True)
class SnowflakeObject:
    """A Snowflake object read by a model table.

    ``kind`` is ``Table`` or ``View`` from connector navigation, ``Table or
    view`` when the connector didn't say, ``SQL reference`` for an object read
    by a native SQL query, and ``SQL not parsed`` when the SQL couldn't be
    resolved or parsed (``native_sql`` then holds the code).
    """

    server: str | None
    warehouse: str | None
    database: str | None
    schema: str | None
    name: str | None
    kind: str
    native_sql: str | None = None


@dataclass(frozen=True)
class Token:
    """A piece of M code: ``string``, ``quoted`` (``#"name"``), ``name`` or ``symbol``."""

    kind: str
    text: str


@dataclass
class _Location:
    """Where the navigation stands while the M code is walked."""

    server: str | None = None
    warehouse: str | None = None
    database: str | None = None
    schema: str | None = None
    objects: list[SnowflakeObject] = field(default_factory=list)


def tokenize(m_code: str) -> list[Token]:
    """Split M code into tokens, dropping spaces and comments."""
    return [
        Token(match.lastgroup, match.group())
        for match in M_TOKEN_PATTERN.finditer(m_code)
        if match.lastgroup and match.lastgroup not in ("comment", "space")
    ]


def unescape_m_string(literal: str) -> str:
    """Return the text of an M string literal such as ``"a""b#(lf)c"``."""
    text = literal[1:-1].replace('""', '"')
    for escape, character in M_STRING_ESCAPES.items():
        text = text.replace(escape, character)
    return text


def _identifier_name(token: Token) -> str:
    """Return the name a ``name`` or ``quoted`` token refers to."""
    return unescape_m_string(token.text[1:]) if token.kind == "quoted" else token.text


def _closing_index(tokens: list[Token], open_index: int) -> int:
    """Return the index of the bracket closing the one at `open_index`, or the end when unbalanced."""
    depth = 0
    for index in range(open_index, len(tokens)):
        text = tokens[index].text
        if tokens[index].kind != "symbol":
            continue
        if text in CLOSING_BRACKETS:
            depth += 1
        elif text in CLOSING_BRACKETS.values():
            depth -= 1
            if depth == 0:
                return index
    return len(tokens)


def _split_top_level(tokens: list[Token], separator: str = ",") -> list[list[Token]]:
    """Split tokens on the separator where it isn't nested in brackets."""
    parts: list[list[Token]] = [[]]
    depth = 0
    for token in tokens:
        if token.kind == "symbol" and token.text in CLOSING_BRACKETS:
            depth += 1
        elif token.kind == "symbol" and token.text in CLOSING_BRACKETS.values():
            depth -= 1
        if depth == 0 and token.kind == "symbol" and token.text == separator:
            parts.append([])
        else:
            parts[-1].append(token)
    return [part for part in parts if part]


def _call_arguments(tokens: list[Token], open_index: int) -> tuple[list[list[Token]], int]:
    """Return the arguments of the call whose ``(`` is at `open_index`, and the index after its ``)``."""
    close = _closing_index(tokens, open_index)
    return _split_top_level(tokens[open_index + 1 : close]), close + 1


def _text_value(tokens: list[Token], names: dict[str, str]) -> str | None:
    """Return the text of a value made of string literals and known names joined with ``&``, else None."""
    parts = []
    for index, token in enumerate(tokens):
        if index % 2:
            if token.text != "&":
                return None
        elif token.kind == "string":
            parts.append(unescape_m_string(token.text))
        elif token.kind in ("name", "quoted") and _identifier_name(token) in names:
            parts.append(names[_identifier_name(token)])
        else:
            return None
    return "".join(parts) if parts and len(tokens) % 2 else None


def _display_value(tokens: list[Token], names: dict[str, str]) -> str:
    """Return the text of a value, or ``{code}`` when it can't be resolved."""
    value = _text_value(tokens, names)
    if value is not None:
        return value
    return "{" + " ".join(_identifier_name(token) if token.kind == "quoted" else token.text for token in tokens) + "}"


def _bindings(tokens: list[Token]) -> dict[str, list[Token]]:
    """Return the top-level ``name = value`` steps of a ``let`` expression, with their value tokens.

    Steps are separated by commas, and the step list is delimited by the
    ``let`` and ``in`` keywords, all outside brackets.
    """
    parts: list[list[Token]] = [[]]
    depth = 0
    for token in tokens:
        if token.kind == "symbol" and token.text in CLOSING_BRACKETS:
            depth += 1
        elif token.kind == "symbol" and token.text in CLOSING_BRACKETS.values():
            depth -= 1
        if depth == 0 and (token.text == "," or (token.kind == "name" and token.text in ("let", "in"))):
            parts.append([])
        else:
            parts[-1].append(token)
    return {
        _identifier_name(part[0]): part[2:]
        for part in parts
        if len(part) > 2 and part[0].kind in ("name", "quoted") and part[1].text == "="  # noqa: PLR2004
    }


def parse_parameters(shared_expressions: dict[str, str]) -> dict[str, str]:
    """Return the text values of the Power Query parameters (``"value" meta [...]``) among the shared expressions."""
    parameters = {}
    for name, expression in shared_expressions.items():
        tokens = tokenize(expression)
        meta = next((index for index, token in enumerate(tokens) if token.text == "meta"), len(tokens))
        value = _text_value(tokens[:meta], {})
        if value is not None:
            parameters[name] = value
    return parameters


def _referenced_queries(
    tokens: list[Token],
    shared_tokens: dict[str, list[Token]],
) -> list[str]:
    """Return the shared queries the code refers to, recursively, dependencies first.

    A table often starts from a shared query that opens the Snowflake
    connection, so its navigation only makes sense after that query's.
    Names of the code's own steps are not references.
    """
    ordered: list[str] = []

    def visit(code: list[Token]) -> None:
        own_steps = set(_bindings(code))
        for token in code:
            if token.kind not in ("name", "quoted"):
                continue
            name = _identifier_name(token)
            if name in shared_tokens and name not in own_steps and name not in ordered:
                ordered.append(name)
                visit(shared_tokens[name])
                ordered.remove(name)
                ordered.append(name)

    visit(tokens)
    return ordered


def _sql_identifier(node: exp.Identifier) -> str:
    """Return a Snowflake identifier as stored: quoted keeps its case, unquoted is uppercased."""
    return node.this if node.quoted else node.this.upper()


def extract_sql_tables(sql: str) -> list[tuple[str | None, str | None, str]]:
    """Return the (database, schema, name) of the tables and views a Snowflake SQL text reads.

    Common table expressions and table functions (``TABLE(...)``,
    ``FLATTEN``) are left out. Missing parts are None.

    Raises:
        sqlglot.errors.SqlglotError: If the SQL can't be parsed.
    """
    tables = []
    for statement in sqlglot.parse(sql, read="snowflake"):
        if statement is None:
            continue
        cte_names = {_sql_identifier(cte.args["alias"].this) for cte in statement.find_all(exp.CTE)}
        for table in statement.find_all(exp.Table):
            if not isinstance(table.this, exp.Identifier):
                continue
            schema, database = table.args.get("db"), table.args.get("catalog")
            name = _sql_identifier(table.this)
            if schema is None and database is None and name in cte_names:
                continue
            tables.append(
                (
                    _sql_identifier(database) if database else None,
                    _sql_identifier(schema) if schema else None,
                    name,
                ),
            )
    return list(dict.fromkeys(tables))


def _record_fields(tokens: list[Token], names: dict[str, str]) -> dict[str, str]:
    """Return the fields of a record's content (``Name="X", Kind="Table"``) as text."""
    fields = {}
    for part in _split_top_level(tokens):
        if len(part) > 2 and part[0].kind in ("name", "quoted") and part[1].text == "=":  # noqa: PLR2004
            fields[_identifier_name(part[0])] = _display_value(part[2:], names)
    return fields


def _navigate(fields: dict[str, str], location: _Location) -> None:
    """Apply a navigation step ``{[Name=..., Kind=...]}`` to the location, recording objects reached."""
    name = fields.get("Name")
    if name is None or location.server is None:
        return
    kind = fields.get("Kind")
    if kind is None:
        if location.database is None:
            kind = "Database"
        elif location.schema is None:
            kind = "Schema"
        else:
            kind = UNKNOWN_OBJECT_KIND
    if kind == "Database":
        location.database, location.schema = name, None
    elif kind == "Schema":
        location.schema = name
    elif kind in OBJECT_KINDS:
        location.objects.append(
            SnowflakeObject(location.server, location.warehouse, location.database, location.schema, name, kind),
        )


def _record_native_query(sql_tokens: list[Token], names: dict[str, str], location: _Location) -> None:
    """Record the objects read by a native query, or one ``SQL not parsed`` row."""
    sql = _text_value(sql_tokens, names)
    try:
        tables = extract_sql_tables(sql) if sql is not None else None
    except sqlglot.errors.SqlglotError:
        tables = None
    if tables is None:
        code = sql if sql is not None else " ".join(token.text for token in sql_tokens)
        location.objects.append(
            SnowflakeObject(
                location.server, location.warehouse, location.database, location.schema, None, SQL_NOT_PARSED, code
            ),
        )
        return
    location.objects.extend(
        SnowflakeObject(
            location.server,
            location.warehouse,
            database or location.database,
            schema or location.schema,
            name,
            SQL_REFERENCE,
            sql,
        )
        for database, schema, name in tables
    )


def _walk(tokens: list[Token], names: dict[str, str], location: _Location) -> None:
    """Follow the Snowflake connection, navigation steps and native queries in code order."""
    index = 0
    while index < len(tokens):
        token = tokens[index]
        is_call = index + 1 < len(tokens) and tokens[index + 1].text == "("
        if token.kind == "name" and is_call and token.text == "Snowflake.Databases":
            arguments, index = _call_arguments(tokens, index + 1)
            location.server = _display_value(arguments[0], names) if arguments else None
            location.warehouse = _display_value(arguments[1], names) if len(arguments) > 1 else None
            location.database = location.schema = None
            continue
        if token.kind == "name" and is_call and token.text == "Value.NativeQuery":
            arguments, index = _call_arguments(tokens, index + 1)
            if arguments:
                _walk(arguments[0], names, location)
            if len(arguments) > 1 and location.server is not None:
                _record_native_query(arguments[1], names, location)
            continue
        if token.text == "{" and index + 1 < len(tokens) and tokens[index + 1].text == "[":
            close = _closing_index(tokens, index + 1)
            _navigate(_record_fields(tokens[index + 2 : close], names), location)
            index = close + 1
            continue
        index += 1


def extract_snowflake_objects(
    expression: str,
    shared_expressions: dict[str, str],
) -> list[SnowflakeObject]:
    """Return the Snowflake objects read by one model table's M expression.

    Args:
        expression: The M expression of the table partition.
        shared_expressions: The model's shared queries and parameters, by name.

    Returns:
        The objects in order of appearance, without duplicates. Empty when
        the expression doesn't use the Snowflake connector.
    """
    shared_tokens = {name: tokenize(code) for name, code in shared_expressions.items()}
    expression_tokens = tokenize(expression)
    queries = [shared_tokens[name] for name in _referenced_queries(expression_tokens, shared_tokens)]
    queries.append(expression_tokens)
    tokens = [token for query in queries for token in query]
    if not any(token.text == "Snowflake.Databases" for token in tokens):
        return []

    names = parse_parameters(shared_expressions)
    for query in queries:
        for step, value_tokens in _bindings(query).items():
            value = _text_value(value_tokens, names)
            if value is not None:
                names.setdefault(step, value)

    location = _Location()
    _walk(tokens, names, location)
    return list(dict.fromkeys(location.objects))
